import { useState } from "react";
import "./Navbar.css";
import logoImg from "../assets/logo.png";

export default function Navbar() {
  const [isOpen, setIsOpen] = useState(false);

  // Object/array pattern
  const logos = [
    {
      id: 1,
      src: logoImg,
      alt: "Sikkim Monasteries Logo"
    }
  ];

  return (
    <nav className="navbar">
      <div className="navbar-container">
        <div className="navbar-left">
          <img src={logos[0].src} alt={logos[0].alt} className="navbar-logo" />
          <h1 className="navbar-title">Sikkim Monasteries</h1>
        </div>

        <button className="navbar-burger" onClick={() => setIsOpen(!isOpen)}>
          ☰
        </button>

        <ul className="navbar-links">
          <li><a href="#home">Home</a></li>
          <li><a href="#about">About</a></li>
          <li><a href="#monasteries">Monasteries</a></li>
          <li><a href="#contact">Contact</a></li>
        </ul>
      </div>

      {isOpen && (
        <ul className="navbar-links-mobile">
          <li><a href="#home">Home</a></li>
          <li><a href="#about">About</a></li>
          <li><a href="#monasteries">Monasteries</a></li>
          <li><a href="#contact">Contact</a></li>
        </ul>
      )}
    </nav>
  );
}
